import { verifyToken } from './tokens';

export interface AuthenticatedUser {
  id: string;
}

// Short-lived cache of verified tokens to avoid repeating HMAC checks on hot paths.
const cache = new Map<string, { user: AuthenticatedUser; expiresAt: number }>();
const CACHE_TTL_MS = 30_000;
const MAX_CACHE_ENTRIES = 10_000;

export async function authenticate(header: string | undefined, now = Date.now()): Promise<AuthenticatedUser | null> {
  if (!header?.startsWith('Bearer ')) return null;
  const token = header.slice('Bearer '.length).trim();

  const cached = cache.get(token);
  if (cached && cached.expiresAt > now) return cached.user;

  const claims = verifyToken(token, 'access', now);
  if (!claims) {
    cache.delete(token);
    return null;
  }

  const user = { id: claims.sub };
  // Never cache past the token's own expiry.
  const expiresAt = Math.min(now + CACHE_TTL_MS, claims.exp * 1000);
  if (cache.size >= MAX_CACHE_ENTRIES) cache.clear();
  cache.set(token, { user, expiresAt });
  return user;
}

export function clearAuthCache(): void {
  cache.clear();
}

const ADMIN_USERS = new Set((process.env.ADMIN_USER_IDS ?? '').split(',').filter(Boolean));

export function isAdmin(user: AuthenticatedUser | null): boolean {
  return !!user && ADMIN_USERS.has(user.id);
}

export async function requireAdmin(header: string | undefined): Promise<AuthenticatedUser> {
  const user = await authenticate(header);
  if (!user || !isAdmin(user)) throw new Error('forbidden');
  return user;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { issueToken, verifyToken, refreshAccessToken } from './tokens';

test('issued access tokens verify', () => {
  const token = issueToken('user_1', 'access');
  assert.equal(verifyToken(token, 'access')?.sub, 'user_1');
});

test('scope is enforced', () => {
  const token = issueToken('user_1', 'refresh');
  assert.equal(verifyToken(token, 'access'), null);
});

test('expired tokens are rejected', () => {
  const issuedAt = Date.now() - 60 * 60 * 1000;
  const token = issueToken('user_1', 'access', issuedAt);
  assert.equal(verifyToken(token, 'access'), null);
});

test('tampered tokens are rejected', () => {
  const token = issueToken('user_1', 'access');
  const [payload] = token.split('.');
  assert.equal(verifyToken(`${payload}.not-a-signature`, 'access'), null);
});

test('refresh retries the session lookup once', async () => {
  let calls = 0;
  const lookup = async () => {
    calls++;
    if (calls === 1) throw new Error('transient');
    return { active: true };
  };
  const token = await refreshAccessToken(issueToken('user_1', 'refresh'), lookup);
  assert.ok(token);
  assert.equal(calls, 2);
});

test('inactive sessions do not refresh', async () => {
  const token = await refreshAccessToken(issueToken('user_1', 'refresh'), async () => ({ active: false }));
  assert.equal(token, null);
});

import { createHmac, timingSafeEqual } from 'node:crypto';

const SECRET = process.env.AUTH_SECRET ?? 'dev-only-secret';
export const ACCESS_TOKEN_TTL_S = 15 * 60;
export const REFRESH_TOKEN_TTL_S = 30 * 24 * 60 * 60;

export interface TokenClaims {
  sub: string;
  exp: number;
  scope: 'access' | 'refresh';
}

const b64 = (input: string | Buffer) => Buffer.from(input).toString('base64url');

function sign(payload: string): string {
  return createHmac('sha256', SECRET).update(payload).digest('base64url');
}

export function issueToken(userId: string, scope: TokenClaims['scope'], now = Date.now()): string {
  const ttl = scope === 'access' ? ACCESS_TOKEN_TTL_S : REFRESH_TOKEN_TTL_S;
  const claims: TokenClaims = { sub: userId, scope, exp: Math.floor(now / 1000) + ttl };
  const payload = b64(JSON.stringify(claims));
  return `${payload}.${sign(payload)}`;
}

export function verifyToken(token: string, scope: TokenClaims['scope'], now = Date.now()): TokenClaims | null {
  const [payload, signature] = token.split('.');
  if (!payload || !signature) return null;
  const expected = Buffer.from(sign(payload));
  const actual = Buffer.from(signature);
  if (expected.length !== actual.length || !timingSafeEqual(expected, actual)) return null;

  const claims = JSON.parse(Buffer.from(payload, 'base64url').toString()) as TokenClaims;
  if (claims.scope !== scope) return null;
  if (claims.exp * 1000 < now) return null;
  return claims;
}

/**
 * Exchanges a refresh token for a new access token. The session lookup is a read, so it is
 * retried once if the session store returns a transient error.
 */
export async function refreshAccessToken(
  refreshToken: string,
  lookupSession: (userId: string) => Promise<{ active: boolean }>,
): Promise<string | null> {
  const claims = verifyToken(refreshToken, 'refresh');
  if (!claims) return null;

  let session: { active: boolean };
  try {
    session = await lookupSession(claims.sub);
  } catch {
    session = await lookupSession(claims.sub);
  }
  return session.active ? issueToken(claims.sub, 'access') : null;
}

// Gateway configuration. Values can be overridden with environment variables.

export interface ServiceConfig {
  name: string;
  baseUrl: string;
}

export const SERVICES: Record<string, ServiceConfig> = {
  auth: { name: 'auth', baseUrl: process.env.AUTH_URL ?? 'http://localhost:4001' },
  orders: { name: 'orders', baseUrl: process.env.ORDERS_URL ?? 'http://localhost:4002' },
  payments: { name: 'payments', baseUrl: process.env.PAYMENTS_URL ?? 'http://localhost:4003' },
  inventory: { name: 'inventory', baseUrl: process.env.INVENTORY_URL ?? 'http://localhost:4004' },
};

// Maximum time the gateway waits for any upstream service before failing the request.
export const UPSTREAM_TIMEOUT_MS = 2000;

// Requests larger than this are rejected before they reach a service.
export const MAX_BODY_BYTES = 256 * 1024;

export const PORT = Number(process.env.PORT ?? 4000);

export const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS ?? 'http://localhost:3000')
  .split(',')
  .map((origin) => origin.trim())
  .filter(Boolean);

export function serviceFor(path: string): ServiceConfig | undefined {
  const [, prefix] = path.split('/');
  return SERVICES[prefix];
}

export function isAllowedOrigin(origin: string | undefined): boolean {
  if (!origin) return true;
  return ALLOWED_ORIGINS.includes(origin);
}

// Paths the load balancer polls; they bypass authentication and logging.
export const HEALTH_PATHS = ['/healthz', '/readyz'];

export function isHealthCheck(path: string): boolean {
  return HEALTH_PATHS.includes(path);
}

import { UPSTREAM_TIMEOUT_MS, type ServiceConfig } from './config';
import { log } from '../utils/logger';

export class UpstreamTimeoutError extends Error {
  constructor(public readonly service: string) {
    super(`Upstream ${service} did not respond within ${UPSTREAM_TIMEOUT_MS}ms`);
    this.name = 'UpstreamTimeoutError';
  }
}

export class UpstreamError extends Error {
  constructor(public readonly service: string, public readonly status: number, body: string) {
    super(`Upstream ${service} returned ${status}: ${body.slice(0, 200)}`);
    this.name = 'UpstreamError';
  }
}

export interface ProxyRequest {
  method: 'GET' | 'POST' | 'PUT' | 'DELETE';
  path: string;
  body?: unknown;
  headers?: Record<string, string>;
}

/**
 * Forwards a request to an internal service and returns the parsed JSON response.
 * The call is aborted after UPSTREAM_TIMEOUT_MS.
 */
export async function forward<T>(service: ServiceConfig, req: ProxyRequest): Promise<T> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), UPSTREAM_TIMEOUT_MS);
  const started = Date.now();

  try {
    const res = await fetch(service.baseUrl + req.path, {
      method: req.method,
      headers: { 'Content-Type': 'application/json', ...req.headers },
      body: req.body === undefined ? undefined : JSON.stringify(req.body),
      signal: controller.signal,
    });
    const text = await res.text();
    log('debug', 'upstream response', { service: service.name, status: res.status, ms: Date.now() - started });
    if (!res.ok) throw new UpstreamError(service.name, res.status, text);
    return (text ? JSON.parse(text) : undefined) as T;
  } catch (err) {
    if (err instanceof Error && err.name === 'AbortError') {
      log('warn', 'upstream timeout', { service: service.name, path: req.path, ms: Date.now() - started });
      throw new UpstreamTimeoutError(service.name);
    }
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

export function statusFor(err: unknown): number {
  if (err instanceof UpstreamTimeoutError) return 504;
  if (err instanceof UpstreamError) return err.status >= 500 ? 502 : err.status;
  return 500;
}

import { serviceFor, isAllowedOrigin, MAX_BODY_BYTES } from './config';
import { forward, statusFor, type ProxyRequest } from './proxy';
import { authenticate } from '../auth/middleware';
import { log } from '../utils/logger';

export interface IncomingRequest extends ProxyRequest {
  origin?: string;
  authorization?: string;
  contentLength?: number;
}

export interface OutgoingResponse {
  status: number;
  body: unknown;
}

const PUBLIC_PATHS = new Set(['/auth/login', '/auth/refresh', '/inventory/products']);

export async function handle(req: IncomingRequest): Promise<OutgoingResponse> {
  if (!isAllowedOrigin(req.origin)) {
    return { status: 403, body: { error: 'origin not allowed' } };
  }
  if ((req.contentLength ?? 0) > MAX_BODY_BYTES) {
    return { status: 413, body: { error: 'request body too large' } };
  }

  const service = serviceFor(req.path);
  if (!service) return { status: 404, body: { error: 'not found' } };

  const headers: Record<string, string> = {};
  if (!PUBLIC_PATHS.has(req.path)) {
    const user = await authenticate(req.authorization);
    if (!user) return { status: 401, body: { error: 'unauthorized' } };
    headers['x-user-id'] = user.id;
  }

  try {
    const body = await forward(service, { ...req, headers });
    return { status: 200, body };
  } catch (err) {
    const status = statusFor(err);
    log('error', 'request failed', { path: req.path, status, error: String(err) });
    return { status, body: { error: status === 504 ? 'upstream timeout' : 'upstream error' } };
  }
}

